import { Chapter, Section } from "../types";

/**
 * Section headings generated by the chapter writer already carry a numeric
 * prefix such as "3.1 从生态学基础到动态方程". The reader's table of
 * contents renders its own `{chapterIndex}.{sectionOrder}` number, so keeping
 * the prefix here would show the number twice (e.g. "3.1 3.1 ..."). Strip the
 * leading "N.M" / "N.M.K" prefix from the extracted title so numbering stays a
 * rendering concern and the stored title is the plain heading text.
 */
const SECTION_NUMBER_PREFIX = /^\s*\d+(?:\.\d+)+[\s、.．-]*/u;

export function markdownToSections(chapter: Chapter, content: string): Section[] {
  const parts = content
    .split(/\n(?=##\s+)/u)
    .map((part) => part.trim())
    .filter(Boolean);

  const sections = parts.length > 0 ? parts : [content.trim()];

  return sections.map((section, index) => {
    const heading = section.match(/^##\s+(.+)$/mu)?.[1];
    const title = heading
      ? (heading.replace(SECTION_NUMBER_PREFIX, "").trim() || heading.trim())
      : (index === 0 ? chapter.title : `小节 ${index + 1}`);
    return {
      id: crypto.randomUUID(),
      chapterId: chapter.id,
      title,
      purpose: index === 0 ? chapter.purpose ?? chapter.description : "支撑本章学习目标。",
      content: section,
      status: "ready",
      order: index,
    };
  });
}
